    + "// `Nat` -> `Int` typechecks only through Numeric Literals §5.1's contextual\n"
    + "// widening, which elaborates through `Num<Int>.fromNat`, the very slot being\n"
    + "// defined.\n"
    + "extern from \"hex:intrinsic\"\n"
    + "    fun intAdd as nativeAdd(left: Int, right: Int): Int\n"
    + "    fun intMultiply as nativeMultiply(left: Int, right: Int): Int\n"
    + "    fun intFromNat as nativeFromNat(value: Nat): Int\n"
    + "    fun intSubtract as nativeSubtract(left: Int, right: Int): Int\n"
    + "    fun intNegate as nativeNegate(value: Int): Int\n"
    + "    fun intEquals as nativeEquals(left: Int, right: Int): Bool\n"
    + "    fun intCompare as nativeCompare(left: Int, right: Int): Ordering\n"
    + "    fun intShow as nativeShow(value: Int): String\n"
    + "    fun intPow as nativePow(left: Int, right: Int): Int\n"
    + "    fun intHash as nativeHash(value: Int): Int\n"
    + "    fun intQuot as nativeQuot(left: Int, right: Int): Int\n"
    + "    fun intRem as nativeRem(left: Int, right: Int): Int\n"
    + "\n"
    + "honor Num<Int> =\n"
    + "    (** The sum of `left` and `right`, exact within the safe range. *)\n"
    + "    add(left, right) = nativeAdd(left, right)\n"
    + "    (** The product of `left` and `right`, exact within the safe range. *)\n"
    + "    multiply(left, right) = nativeMultiply(left, right)\n"
    + "    (** The natural number `value` as an `Int`. Total: every `Nat` is an `Int`. *)\n"
    + "    fromNat(value) = nativeFromNat(value)\n"
    + "\n"
    + "honor Signed<Int> =\n"
    + "    (** The difference of `left` and `right`, exact within the safe range. *)\n"
    + "    subtract(left, right) = nativeSubtract(left, right)\n"
    + "    (** The additive inverse of `value`. Total: the safe range is symmetric. *)\n"
    + "    negate(value) = nativeNegate(value)\n"
    + "    (** The integer `value` as an `Int`, which is `value` itself. *)\n"
    + "    fromInt(value) = value\n"
    + "\n"
    + "honor Eq<Int> =\n"
    + "    (** Whether `left` and `right` are the same integer. *)\n"
    + "    equals(left, right) = nativeEquals(left, right)\n"
    + "\n"
    + "honor Ord<Int> =\n"
    + "    (** How `left` orders against `right`, by numeric value. *)\n"
    + "    compare(left, right) = nativeCompare(left, right)\n"
    + "\n"
    + "honor Show<Int> =\n"
    + "    (** The decimal form of `value`, with a leading `-` when it is negative. *)\n"
    + "    show(value) = nativeShow(value)\n"
    + "\n"
    + "honor Pow<Int> =\n"
    + "    (** `left` raised to the power `right`. Raises `NegativeExponentError` when\n"
    + "        `right` is negative: a negative power of an integer is not an integer. *)\n"
    + "    pow(left, right) =\n"
    + "        if right < 0 then\n"
    + "            throw(NegativeExponentError(\"an integer exponent cannot be negative\"))\n"
