    + "    (** A hash of `value`. Equal `Int`s hash equally, which is what `Eq` above\n"
    + "        is checked against. *)\n"
    + "    hash(value) = nativeHash(value)\n"
    + "\n"
    + "honor Integral<Int> =\n"
    + "    (** The truncated quotient of `left` divided by `right`, rounding toward\n"
    + "        zero. Raises `DivideByZeroError` when `right` is zero. *)\n"
    + "    quot(left, right) =\n"
    + "        if right == 0 then\n"
    + "            throw(DivideByZeroError(\"Int.quot: divisor is zero\"))\n"
    + "        else\n"
    + "            nativeQuot(left, right)\n"
    + "\n"
    + "    (** The truncated remainder of `left` divided by `right`, taking the sign of\n"
